import torch

def forward(module, *inputs):
    ids = inputs[0]
    # the embedding table arrives as a constant: runtime operand, else module attribute
    if len(inputs) > 1:
        table = inputs[1]
    elif hasattr(module, "table"):
        table = module.table
    else:
        table = module.weight
    # step 1: one_hot_b(ids, vocab) -> selector (1, tokens, vocab); broadcast eq vs constant index vector, no gather
    flat = ids.reshape(-1).long()
    sel = (flat.unsqueeze(0).unsqueeze(2) == torch.arange(table.shape[0], device=ids.device)).to(table.dtype)
    # step 2: bmm b=1, m=tokens, k=vocab, n=dim: out = sel @ table.unsqueeze(0)
    return torch.bmm(sel, table.unsqueeze(0).to(sel.dtype))

import torch


def forward(module, ids):
    table = getattr(module, 'table', None)
    if table is None:
        table = module.weight
    # Step 1 (one_hot_b): sel (1, tokens, vocab), sel[0, i, j] = 1.0 iff ids[i] == j, table dtype
    flat = ids.reshape(-1).long()
    sel = torch.nn.functional.one_hot(flat, int(table.shape[0])).to(table.dtype).unsqueeze(0)
    # Step 2 (bmm b=1, m=tokens, k=vocab, n=dim): out = sel @ table.unsqueeze(0)
    return torch.bmm(sel, table.unsqueeze(0))
